/* ===== test_motor_controller.c ===== */
#include "unity.h"
#include "motor_controller.h"
#include "mock_stm32f4xx_hal.h"
#include "mock_position_sensing.h"
// External TIM handle as per production
TIM_HandleTypeDef htim3;
#define MOTOR_PWM_HANDLE      htim3
#define MOTOR_PWM_CHANNEL     TIM_CHANNEL_1
#define MOTOR_GPIO_PORT_DIR   GPIOB
#define MOTOR_PIN_DIR_FWD     GPIO_PIN_0
#define MOTOR_PIN_DIR_REV     GPIO_PIN_1
#define VALID_TARGET          2
#define INVALID_TARGET        6
void setUp(void) { }
void tearDown(void) { }
void test_MC_01_Init_sets_safe_state_and_starts_PWM(void) {GPIO_InitTypeDef expect_struct={.Pin=MOTOR_PIN_DIR_FWD|MOTOR_PIN_DIR_REV,.Mode=GPIO_MODE_OUTPUT_PP,.Pull=GPIO_NOPULL,.Speed=GPIO_SPEED_FREQ_LOW};HAL_GPIO_Init_Expect(MOTOR_GPIO_PORT_DIR,&expect_struct);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_RESET);HAL_TIM_PWM_Start_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_Init();TEST_ASSERT_EQUAL_UINT8(0U,MotorController_IsMoving());TEST_ASSERT_EQUAL(MOTOR_STATE_STOPPED,MotorController_GetState());uint8_t tgt=111;TEST_ASSERT_EQUAL_UINT8(1,MotorController_GetTarget(&tgt));TEST_ASSERT_EQUAL_UINT8(0,tgt);}
void test_MC_02_Move_forward_when_current_LT_target(void){uint8_t current=1;PositionSensing_GetPosition_ExpectAnyArgsAndReturn(1);PositionSensing_GetPosition_ReturnArrayThruPtr_pos_out(&current,1);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_SET);HAL_TIM_PWM_Start_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_MoveTo(4);TEST_ASSERT_EQUAL_UINT8(1,MotorController_IsMoving());TEST_ASSERT_EQUAL(MOTOR_STATE_MOVING_FWD,MotorController_GetState());}
void test_MC_03_Move_reverse_when_current_GT_target(void){uint8_t current=5;PositionSensing_GetPosition_ExpectAnyArgsAndReturn(1);PositionSensing_GetPosition_ReturnArrayThruPtr_pos_out(&current,1);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_SET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_RESET);HAL_TIM_PWM_Start_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_MoveTo(2);TEST_ASSERT_EQUAL_UINT8(1,MotorController_IsMoving());TEST_ASSERT_EQUAL(MOTOR_STATE_MOVING_REV,MotorController_GetState());}
void test_MC_04_No_movement_when_already_at_target_calls_Abort(void){uint8_t current=3;PositionSensing_GetPosition_ExpectAnyArgsAndReturn(1);PositionSensing_GetPosition_ReturnArrayThruPtr_pos_out(&current,1);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_RESET);HAL_TIM_PWM_Stop_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_MoveTo(3);TEST_ASSERT_EQUAL_UINT8(0,MotorController_IsMoving());TEST_ASSERT_EQUAL(MOTOR_STATE_STOPPED,MotorController_GetState());}
void test_MC_05_Abort_if_position_invalid_at_MoveTo(void){uint8_t dontcare=0;PositionSensing_GetPosition_ExpectAnyArgsAndReturn(0);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_RESET);HAL_TIM_PWM_Stop_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_MoveTo(3);TEST_ASSERT_EQUAL_UINT8(0,MotorController_IsMoving());TEST_ASSERT_EQUAL(MOTOR_STATE_STOPPED,MotorController_GetState());}
void test_MC_06_Update_does_nothing_if_not_moving(void){MotorController_Abort();MotorController_Update();TEST_ASSERT_EQUAL_UINT8(0,MotorController_IsMoving());TEST_ASSERT_EQUAL(MOTOR_STATE_STOPPED,MotorController_GetState());}
void test_MC_07_Update_abort_when_GetPosition_invalid_while_moving(void){uint8_t cur=1;PositionSensing_GetPosition_ExpectAnyArgsAndReturn(1);PositionSensing_GetPosition_ReturnArrayThruPtr_pos_out(&cur,1);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_SET);HAL_TIM_PWM_Start_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_MoveTo(4);PositionSensing_Update_Expect();PositionSensing_GetPosition_ExpectAnyArgsAndReturn(0);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_RESET);HAL_TIM_PWM_Stop_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_Update();TEST_ASSERT_EQUAL_UINT8(0,MotorController_IsMoving());TEST_ASSERT_EQUAL(MOTOR_STATE_STOPPED,MotorController_GetState());}
void test_MC_08_Update_abort_when_IsAtTarget_true_while_moving(void){uint8_t cur=1;PositionSensing_GetPosition_ExpectAnyArgsAndReturn(1);PositionSensing_GetPosition_ReturnArrayThruPtr_pos_out(&cur,1);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_SET);HAL_TIM_PWM_Start_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_MoveTo(4);PositionSensing_Update_Expect();cur=4;PositionSensing_GetPosition_ExpectAnyArgsAndReturn(1);PositionSensing_GetPosition_ReturnArrayThruPtr_pos_out(&cur,1);PositionSensing_IsAtTarget_ExpectAndReturn(4,1);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_RESET);HAL_TIM_PWM_Stop_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_Update();TEST_ASSERT_EQUAL_UINT8(0,MotorController_IsMoving());TEST_ASSERT_EQUAL(MOTOR_STATE_STOPPED,MotorController_GetState());}
void test_MC_09_Update_continue_while_not_at_target(void){uint8_t cur=2;PositionSensing_GetPosition_ExpectAnyArgsAndReturn(1);PositionSensing_GetPosition_ReturnArrayThruPtr_pos_out(&cur,1);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_SET);HAL_TIM_PWM_Start_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_MoveTo(4);PositionSensing_Update_Expect();cur=3;PositionSensing_GetPosition_ExpectAnyArgsAndReturn(1);PositionSensing_GetPosition_ReturnArrayThruPtr_pos_out(&cur,1);PositionSensing_IsAtTarget_ExpectAndReturn(4,0);MotorController_Update();TEST_ASSERT_EQUAL_UINT8(1,MotorController_IsMoving());}
void test_MC_10_Abort_sets_safe_outputs_and_stops_pwm(void){HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_RESET);HAL_TIM_PWM_Stop_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_Abort();TEST_ASSERT_EQUAL_UINT8(0,MotorController_IsMoving());}
void test_MC_11_GetTarget_valid_stopped_and_ptr_valid(void){MotorController_Abort();MotorController_MoveTo(VALID_TARGET);MotorController_Abort();uint8_t tgt=123;TEST_ASSERT_EQUAL_UINT8(1,MotorController_GetTarget(&tgt));TEST_ASSERT_EQUAL_UINT8(VALID_TARGET,tgt);}
void test_MC_12_GetTarget_returns_0_when_moving(void){uint8_t cur=0;PositionSensing_GetPosition_ExpectAnyArgsAndReturn(1);PositionSensing_GetPosition_ReturnArrayThruPtr_pos_out(&cur,1);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_SET);HAL_TIM_PWM_Start_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_MoveTo(VALID_TARGET);uint8_t tgt=99;TEST_ASSERT_EQUAL_UINT8(0,MotorController_GetTarget(&tgt));}
void test_MC_13_GetTarget_returns_0_on_NULL_ptr(void){MotorController_Abort();TEST_ASSERT_EQUAL_UINT8(0,MotorController_GetTarget(NULL));}
void test_MC_14_GetTarget_returns_0_when_target_out_of_range(void){MotorController_Abort();PositionSensing_GetPosition_ExpectAnyArgsAndReturn(0);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_FWD,GPIO_PIN_RESET);HAL_GPIO_WritePin_Expect(MOTOR_GPIO_PORT_DIR,MOTOR_PIN_DIR_REV,GPIO_PIN_RESET);HAL_TIM_PWM_Stop_Expect(&MOTOR_PWM_HANDLE,MOTOR_PWM_CHANNEL);MotorController_MoveTo(INVALID_TARGET);uint8_t tgt=55;TEST_ASSERT_EQUAL_UINT8(0,MotorController_GetTarget(&tgt));}